package org.humanjourney.core.mapfeature;
import java.util.*;
import com.google.gson.*;
import org.humanjourney.core.geography.DiscoveryLedger;
import org.humanjourney.core.water.WaterGeography.Point;
public record MapFeature(View view,double discoveryRadius){
 public enum Type{OCEAN,SEA,GULF,BAY,STRAIT,LAKE,RIVER;public String label(){return name().charAt(0)+name().substring(1).toLowerCase(Locale.ROOT);}}
 /** Deliberately excludes discovery radius and every server gameplay/context field. */
 public record View(String id,String label,Type type,String dimension,int priority,FeatureGeometry geometry){public View{if(!DiscoveryLedger.validId(id)||label==null||label.isBlank()||label.length()>128||label.chars().anyMatch(Character::isISOControl)||type==null||dimension==null||dimension.length()>256||!dimension.matches("[a-z0-9_.-]+:[a-z0-9_./-]+")||Math.abs((long)priority)>1000000||geometry==null)throw new IllegalArgumentException("invalid feature metadata");}}
 public MapFeature{Objects.requireNonNull(view);if(!Double.isFinite(discoveryRadius)||discoveryRadius<1||discoveryRadius>64)throw new IllegalArgumentException("discovery_radius must be finite 1..64");}
 private static void keys(JsonObject o,Set<String> allowed){for(String k:o.keySet())if(!allowed.contains(k))throw new IllegalArgumentException("unknown feature field: "+k);}
 private static String string(JsonObject o,String key){var e=o.get(key);if(e==null||!e.isJsonPrimitive()||!e.getAsJsonPrimitive().isString())throw new IllegalArgumentException("missing/invalid "+key);return e.getAsString();}
 private static double number(JsonObject o,String key,double fallback){if(!o.has(key))return fallback;var e=o.get(key);if(!e.isJsonPrimitive()||!e.getAsJsonPrimitive().isNumber())throw new IllegalArgumentException("invalid "+key);double v=e.getAsDouble();if(!Double.isFinite(v))throw new IllegalArgumentException("non-finite "+key);return v;}
 public static MapFeature parse(JsonElement input){if(input==null||!input.isJsonObject())throw new IllegalArgumentException("feature must be object");var o=input.getAsJsonObject();keys(o,Set.of("schema_version","id","label","feature_type","dimension","priority","discovery_radius","geometry"));if(number(o,"schema_version",-1)!=1)throw new IllegalArgumentException("unsupported feature schema");String type=string(o,"feature_type");if(!type.matches("ocean|sea|gulf|bay|strait|lake|river"))throw new IllegalArgumentException("unsupported feature type");double priority=number(o,"priority",0);if(priority!=Math.rint(priority)||Math.abs(priority)>1000000)throw new IllegalArgumentException("invalid feature priority");var g=o.getAsJsonObject("geometry");if(g==null)throw new IllegalArgumentException("missing geometry");keys(g,Set.of("type","points"));String kind=string(g,"type");if(!Set.of("polygon","polyline").contains(kind))throw new IllegalArgumentException("unsupported feature geometry");var array=g.getAsJsonArray("points");if(array==null||array.size()>512)throw new IllegalArgumentException("invalid feature points");var points=new ArrayList<Point>();for(var e:array){if(!e.isJsonArray()||e.getAsJsonArray().size()!=2)throw new IllegalArgumentException("point must be [X,Z]");var p=e.getAsJsonArray();for(var n:p)if(!n.isJsonPrimitive()||!n.getAsJsonPrimitive().isNumber())throw new IllegalArgumentException("non-numeric feature point");points.add(new Point(p.get(0).getAsDouble(),p.get(1).getAsDouble()));}return new MapFeature(new View(string(o,"id"),string(o,"label"),Type.valueOf(type.toUpperCase(Locale.ROOT)),string(o,"dimension"),(int)priority,new FeatureGeometry(FeatureGeometry.Kind.valueOf(kind.toUpperCase(Locale.ROOT)),points,null)),number(o,"discovery_radius",8));}
}
